  function renderResource(){var list=state.servers,t=totals(),monthCost=0;list.forEach(function(s){var p=Number(s.renewal_price||0),d=Number(s.renewal_cycle_days||0);if(p&&d)monthCost+=p*(30/d);else monthCost+=p});var byDay={};list.forEach(function(s){(s.daily_traffic||[]).forEach(function(d){var o=byDay[d.date]||(byDay[d.date]={date:d.date,uplink:0,downlink:0,total:0});o.uplink+=d.uplink||0;o.downlink+=d.downlink||0;o.total=o.uplink+o.downlink})});var seven=Object.keys(byDay).sort().map(function(k){return byDay[k]}).slice(-7),ranked=list.slice().sort(function(a,b){return pct(b.traffic_used,b.traffic_limit)-pct(a.traffic_used,a.traffic_limit)}),heat=list.slice().sort(function(a,b){return (b.cpu_pct||0)-(a.cpu_pct||0)}),soon=list.slice().sort(function(a,b){return String(a.expires_at||'9999').localeCompare(String(b.expires_at||'9999'))}).slice(0,6);main.innerHTML='<section class="subpage"><p class="lead">'+t.online+'/'+t.all+' 台在线。聚合 Komari 实时指标与历史流量。</p><section class="kpi"><article><div class="lbl">节点月成本</div><div class="val">'+fmtMoney(monthCost,list[0]&&list[0].renewal_currency)+'</div><div class="sub">按账单天数折算</div></article><article><div class="lbl">周期用量</div><div class="val">'+fmtBytes(t.used,1)+'</div><div class="sub">限额 '+fmtBytes(t.limit,1)+'</div></article><article><div class="lbl">在线</div><div class="val">'+t.online+'/'+t.all+'</div><div class="sub">实时状态</div></article><article><div class="lbl">总下行</div><div class="val">'+fmtSpeed(t.down)+'</div><div class="sub">实时速率</div></article><article><div class="lbl">总上行</div><div class="val">'+fmtSpeed(t.up)+'</div><div class="sub">实时速率</div></article></section><section class="panels" style="margin-top:16px"><div class="panel"><div class="panel-h"><h3>近 7 日上下行</h3><span class="hero-sub">金 = 上行</span></div>'+Charts.stacked(seven,{w:520,h:150,tips:trafficTips(seven)})+'</div><div class="panel"><div class="panel-h"><h3>额度使用率</h3></div>'+ranked.slice(0,6).map(function(s){var p=pct(s.traffic_used,s.traffic_limit);return '<div class="rank" style="margin:12px 0"><div style="display:flex;justify-content:space-between;font-size:11px"><span>'+esc(s.name)+'</span><b>'+Math.round(p)+'%</b></div><i style="--p:'+p+'%"></i></div>'}).join('')+'</div></section><div class="panel" style="margin-top:16px"><div class="panel-h"><h3>资源压力</h3><span class="hero-sub">CPU · 内存 · 硬盘</span></div><table class="heat"><thead><tr><th>服务器</th><th>CPU</th><th>内存</th><th>硬盘</th><th>Load</th></tr></thead><tbody>'+heat.map(function(s){return '<tr><td>'+esc(s.name)+'</td><td>'+Math.round(s.cpu_pct||0)+'%</td><td>'+Math.round(pct(s.mem_used,s.mem_total))+'%</td><td>'+Math.round(pct(s.disk_used,s.disk_total))+'%</td><td>'+esc((s.loadavg||'—').split(' ')[0])+'</td></tr>'}).join('')+'</tbody></table></div><div class="panel" style="margin-top:16px"><div class="panel-h"><h3>续费与到期</h3><span class="hero-sub">扩展元数据可补充人民币价格</span></div><div class="timeline">'+soon.map(function(s){var days=s.expires_at?Math.ceil((new Date(s.expires_at)-new Date())/86400000):null;return '<article><div class="lbl">'+esc(s.expires_at?s.expires_at.slice(0,10):'未设置')+'</div><b>'+esc(s.name)+'</b><span class="hero-sub">'+(days==null?'—':days+' 天')+' · '+fmtRenewal(s)+'</span></article>'}).join('')+'</div></div></section>'+cycleBlock()}
  function fmtMoney(v,c){if(!v)return '—';return API.currencySymbol(c||'')+Number(v).toFixed(Number(v)>=100?0:2)}
  function fmtRenewal(s){if(s.renewal_price_cny!=null&&Number(s.renewal_price_cny)>0)return '¥'+Number(s.renewal_price_cny).toFixed(0)+' / '+(s.renewal_cycle_days||'?')+'d';return fmtMoney(s.renewal_price,s.renewal_currency)+' / '+(s.renewal_cycle_days||'?')+'d'}
