  function pingPage(s){var hist=detailSeries(s),vals=hist?hist.values:[];return '<article><div class="panel-h"><h3>Latency / Packet Loss</h3>'+rangeButtons()+'</div>'+targetButtons(s)+'<div class="chart-fill" style="height:320px">'+(vals.length?Charts.spark(vals,{w:960,h:280,color:css('--ink','#d5d0c4'),tips:(hist.times||[]).map(function(t,i){return new Date(t).toLocaleString()+' · '+(vals[i]<0?'丢包':vals[i]+' ms')})}):'<div class="state"><p>没有历史 Ping 数据或正在读取。</p></div>')+'</div><section class="kpi" style="margin-top:14px">'+(s.ping||[]).slice(0,5).map(function(p){return '<article><div class="lbl">'+esc(p.label)+'</div><div class="val">'+(p.current_ms<0?'—':p.current_ms+'ms')+'</div><div class="sub">loss '+p.loss_pct.toFixed(2)+'% · avg '+Math.round(p.avg_ms||0)+'</div></article>'}).join('')+'</section></article>'}
  function trafficPage(s){var st=dailyStats(s),rows=s.daily_traffic||[];return '<article>'+quotaBar(s)+'<section class="kpi" style="margin-top:16px"><article><div class="lbl">已用</div><div class="val">'+fmtBytes(s.traffic_used,1)+'</div><div class="sub">限额 '+fmtBytes(s.traffic_limit,1)+'</div></article><article><div class="lbl">上行</div><div class="val">'+fmtBytes(s.traffic_used_up,1)+'</div><div class="sub">本周期</div></article><article><div class="lbl">下行</div><div class="val">'+fmtBytes(s.traffic_used_down,1)+'</div><div class="sub">本周期</div></article><article><div class="lbl">最高日</div><div class="val">'+fmtBytes(st.high,1)+'</div><div class="sub">日均 '+fmtBytes(st.avg,1)+'</div></article><article><div class="lbl">周期</div><div class="val">'+esc((s.period_start||'—').slice(5))+'</div><div class="sub">至 '+esc((s.period_end||'—').slice(5))+'</div></article></section><div class="panel" style="margin-top:16px"><div class="panel-h"><h3>近 7 日流量</h3><span class="hero-sub">Komari traffic.up/down</span></div>'+Charts.stacked(rows,{w:960,h:220,tips:trafficTips(rows)})+'</div><section class="day-grid">'+rows.map(function(d){return '<article><div class="lbl">'+esc(d.date.slice(5))+'</div><div class="val" style="font-size:16px">'+fmtBytes(d.total,1)+'</div><div class="hero-sub">↑ '+fmtBytes(d.uplink,1)+' · ↓ '+fmtBytes(d.downlink,1)+'</div></article>'}).join('')+'</section></article>'}
  function routesPage(s){var rows=s.return_routes||[];return '<article><div class="panel-h"><h3>三网回程</h3><span class="hero-sub">扩展元数据</span></div><div class="route-cards">'+(rows.length?rows.map(function(r){return '<article class="route-card"><div class="car">'+esc(CARRIER[r.carrier]||r.carrier||'route')+'</div><h3>'+esc(r.route_type||'—')+'</h3>'+(r.region?'<div class="hero-sub">'+esc(r.region)+'</div>':'')+'</article>'}).join(''):'<div class="state" style="grid-column:1/-1"><h2>暂无回程数据</h2><p>Komari 原生不提供此字段；在 metadata/nodes.json 按 UUID 补充即可。</p></div>')+'</div></article>'}
  function systemPage(s){var cells=[['系统',s.os],['内核',s.kernel],['架构',s.arch],['虚拟化',s.virtualization],['处理器',(s.cpu_model||'—')+' · '+s.cpu_cores+'C / '+s.cpu_threads+'T'],['GPU',s.gpu||'—'],['负载',s.loadavg],['分组',s.group||'—'],['标签',s.tags||'—'],['到期',s.expires_at?s.expires_at.slice(0,10):'—'],['续费',fmtRenewal(s)],['周期',(s.period_start||'—')+' → '+(s.period_end||'—')]];return '<article><section class="spec">'+cells.map(function(c){return '<article><div class="lbl">'+esc(c[0])+'</div><div class="val">'+esc(c[1]||'—')+'</div></article>'}).join('')+'</section></article>'}
  function renderWindow(uuid,page){var s=nodeByUuid(uuid);if(!s){hideWindow();return}if(!targetKey&&s.ping&&s.ping[0])targetKey=s.ping[0].key;winTitle.textContent=s.name;winKicker.textContent=(s.region_country||'NODE')+' / '+(s.region_city||s.region_name||'DETAIL');Array.prototype.forEach.call(stageTabs.querySelectorAll('[data-page]'),function(b){b.classList.toggle('is-on',b.dataset.page===page)});if(page==='ping')winBody.innerHTML=pingPage(s);else if(page==='traffic')winBody.innerHTML=trafficPage(s);else if(page==='routes')winBody.innerHTML=routesPage(s);else if(page==='system')winBody.innerHTML=systemPage(s);else winBody.innerHTML=overviewPage(s);overlay.hidden=false;document.body.style.overflow='hidden';if((page==='ping'||page==='overview')&&s.ping&&s.ping.length){var key=s.uuid+':'+range+':'+(targetKey||s.ping[0].key);if(!seriesCache[key])loadSeries(s.uuid,targetKey||s.ping[0].key).then(function(){if(route().uuid===s.uuid)renderWindow(s.uuid,route().page)})}}
