  function render(){var r=route();renderChrome(r);if(loading&&!state.servers.length){main.innerHTML=empty('正在连接 Komari','读取节点与实时状态。');renderFoot();hideWindow();return}if(error&&!state.servers.length){main.innerHTML='<div class="error-note">'+esc(error)+'</div>'+empty('无法读取 Komari','请确认主题与 Komari 同源部署，且 /api/rpc2 可访问。');renderFoot();hideWindow();return}if(r.home==='network')renderNetwork();else if(r.home==='resource')renderResource();else renderNodes();renderFoot();if(r.uuid)renderWindow(r.uuid,r.page);else hideWindow()}
