  function bindGlobe(){var a=document.getElementById('atlas');if(!a)return;a.addEventListener('pointerdown',function(e){globeDrag={x:e.clientX,y:e.clientY,lon:globeLon,lat:globeLat,moved:false};e.preventDefault()});if(globeGlobalBound)return;globeGlobalBound=true;document.addEventListener('pointermove',function(e){if(!globeDrag)return;var dx=e.clientX-globeDrag.x,dy=e.clientY-globeDrag.y;if(Math.abs(dx)+Math.abs(dy)>4)globeDrag.moved=true;globeLon=wrapLon(globeDrag.lon-dx*.45);globeLat=Math.max(-70,Math.min(70,globeDrag.lat+dy*.3));var cur=document.getElementById('atlas');if(cur){cur.outerHTML=globeSvg();bindGlobe()}});document.addEventListener('pointerup',function(){if(globeDrag&&globeDrag.moved)skipGlobeClick=true;globeDrag=null})}
